            )
        else:
            raise ValueError("unknown coupon")
    if total < 0:
        total = Decimal("0")
    return {"lines": lines, "total": total.quantize(Decimal("0.01"))}


def same(a, b):
    if a.keys() != b.keys():
        return False
    if repr(a["total"]) != repr(b["total"]):
        return False
    if len(a["lines"]) != len(b["lines"]):
        return False
    for x, y in zip(a["lines"], b["lines"]):
        if x.keys() != y.keys():
